    it('should update error when array is changed', async () => {
      type FormValues = {
        test: { value: string }[];
      };

      const App = () => {
        const {
          register,
          control,
          formState: { errors },
        } = useForm<FormValues>({
          mode: 'onChange',
          resolver: async (data): Promise<ResolverResult<FormValues>> => {
            const fieldErrors: { test?: any } = {};
            if (data.test.length > 4) {
              fieldErrors.test = {
                type: 'toobig',
                message: 'WAY too many items',
              };
            } else if (data.test.length > 3) {
              fieldErrors.test = { type: 'toobig', message: 'Too many items' };
            }
            for (const [index, item] of data.test.entries()) {
              if (item.value === '') {
                fieldErrors.test = fieldErrors.test || [];
                fieldErrors.test[index] = {
                  value: { type: 'required', message: 'Required' },
                };
              }
            }

            if (Object.keys(fieldErrors).length === 0) {
              return {
                values: data,
                errors: {},
              };
            }

            return {
              values: {},
              errors: fieldErrors,
            };
          },
          defaultValues: {
            test: [{ value: '0' }, { value: '1' }, { value: '2' }],
          },
        });
        const { fields, append, remove } = useFieldArray({
          name: 'test',
          control,
        });

        return (
          <form>
            {errors.test?.type && <p>Array error: {errors.test.message}</p>}
            {fields.map((item, i) => (
              <div key={item.id}>
                <input {...register(`test.${i}.value` as const)} />
                <button type="button" onClick={() => remove(i)}>
                  remove
                </button>
                {errors.test?.[i]?.value && (
                  <span>
                    Item {i} error: {errors.test?.[i]?.value?.message}
                  </span>
                )}
              </div>
            ))}
            <button
              type="button"
              onClick={() =>
                append({
                  value: fields.length.toString(),
                })
              }
            >
              append
            </button>
          </form>
        );
      };

      render(<App />);

      await waitFor(() =>
        expect(screen.queryByText('Array error:')).not.toBeInTheDocument(),
      );

      fireEvent.click(screen.getByRole('button', { name: 'append' }));

      await waitFor(() =>
        expect(
          screen.queryByText('Array error: Too many items'),
        ).toBeInTheDocument(),
      );

      expect(getFieldState('test2.sub').isValidating).toBe(true);
      expect(formState.validatingFields).toStrictEqual({
        test2: { sub: true },
      });
    });

    await act(async () => {
      jest.advanceTimersByTime(1000);
    });

    await waitFor(() => {
      expect(formState.isValidating).toBe(false);
      expect(getFieldState('test1').isValidating).toBe(false);
      expect(getFieldState('test2.sub').isValidating).toBe(false);
      expect(formState.validatingFields).toStrictEqual({});
    });
  });

  it('should put resolver field-array root errors under root - issue #13104', async () => {
    type FormValues = { items: { name: string }[] };

    const resolver: Resolver<FormValues> = async (values) => {
      if (!values.items || values.items.length < 1) {
        return {
          values: {},
          errors: {
            items: {
              type: 'min',
              message: 'at_least_1_item',
            },
          },
        };
      }

      return { values, errors: {} };
    };

    let triggerErrors: FieldErrors<FormValues> | undefined;

    const App = () => {
      const {
        control,
        trigger,
        formState: { errors },
      } = useForm<FormValues>({
        defaultValues: { items: [] },
        resolver,
      });

      useFieldArray({ control, name: 'items' });
      triggerErrors = errors;

      return (
        <button type="button" onClick={() => trigger('items')}>
          trigger
        </button>
      );
    };

    render(<App />);

    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: /trigger/i }));
    });

    await waitFor(() => {
      expect(triggerErrors?.items?.root?.message).toBe('at_least_1_item');
    });
  });

  it('should preserve resolver nested field-array item errors on trigger', async () => {
    type FormValues = { items: { name: string }[] };

    const nestedItemErrors: FieldErrors<FormValues> = {
      items: [
        {
          name: {
            type: 'required',
            message: 'name_required',
          },
        },
      ],
    };

    const resolver: Resolver<FormValues> = async () => ({
      values: {},
      errors: nestedItemErrors,
    });

    let triggerErrors: FieldErrors<FormValues> | undefined;

    const App = () => {
      const {
        control,
        trigger,
        formState: { errors },
      } = useForm<FormValues>({
        defaultValues: { items: [{ name: '' }] },
        resolver,
      });

      useFieldArray({ control, name: 'items' });
      triggerErrors = errors;

      return (
        <button type="button" onClick={() => trigger('items')}>
          trigger
        </button>
      );
    };

    render(<App />);

    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: /trigger/i }));
    });

    await waitFor(() => {
      expect(triggerErrors?.items?.[0]?.name?.message).toBe('name_required');
      expect(triggerErrors?.items?.root).toBeUndefined();
    });
  });
});
